function animalIconSrc(iconId){
  const id = String(iconId || '');
  if(ANIMAL_ICON_SRCS[id]) return ANIMAL_ICON_SRCS[id];
  // deterministic fallback from id string if present
  return ANIMAL_ICON_SRCS['1'];
}
function randomAnimalIconId(){
  return String(1 + Math.floor(Math.random() * ANIMAL_ICON_COUNT));
}
function animalIconImg(iconId, cls=''){
  const src = animalIconSrc(iconId);
  return `<img class="animal-icon ${cls}" src="${src}" alt="" width="48" height="48" decoding="async" loading="lazy">`;
}

