function currentLogoSrc(){
  const scheme = document.documentElement.dataset.theme || 'classic';
  return THEME_LOGO_SRCS[scheme] || THEME_LOGO_SRCS.classic || LOGO_SRC;
}
function refreshLogos(){
  const src = currentLogoSrc();
  document.querySelectorAll('img.logo, img.side-logo').forEach(img => {
    if (img.getAttribute('src') !== src) img.setAttribute('src', src);
  });
}

async function copyText(text){
  const t=String(text||'');
  try{
    if(navigator.clipboard?.writeText){ await navigator.clipboard.writeText(t); return true; }
  }catch(_){}
  try{
    const ta=document.createElement('textarea');
    ta.value=t; ta.setAttribute('readonly',''); ta.style.position='fixed'; ta.style.left='-9999px';
    document.body.appendChild(ta); ta.select();
    const ok=document.execCommand('copy');
    ta.remove();
    return ok;
  }catch(_){ return false; }
}
async function pasteText(){
  try{
    if(navigator.clipboard?.readText) return await navigator.clipboard.readText();
  }catch(_){}
  return '';
}

function quickNav(items){
  if(!items||!items.length) return '';
  return `<nav class="quick-nav" role="navigation" aria-label="Быстрый доступ"><div class="quick-nav-inner">${items.map(it=>`<button type="button" class="quick-nav-btn" data-jump="${it.id}">${it.label}</button>`).join('')}</div></nav>`;
}
function bindQuickNav(scope){
  const root=scope||document;
  root.querySelectorAll('.quick-nav-btn[data-jump]').forEach(b=>{
    b.addEventListener('click',()=>{
      const el=document.getElementById(b.dataset.jump);
      if(!el) return;
      el.scrollIntoView({behavior:'smooth',block:'start'});
      el.classList.add('quick-nav-target');
      setTimeout(()=>el.classList.remove('quick-nav-target'),1100);
      root.querySelectorAll('.quick-nav-btn').forEach(x=>x.classList.toggle('active',x===b));
    });
  });
}

