const apiCache=new Map(),apiPending=new Map();

function toast(msg, kind='ok'){
  let host=document.querySelector('#mostikToasts');
  if(!host){
    host=document.createElement('div');
    host.id='mostikToasts';
    host.className='mostik-toasts';
    document.body.appendChild(host);
  }
  const el=document.createElement('div');
  el.className=`mostik-toast mostik-toast-${kind}`;
  el.textContent=msg;
  host.appendChild(el);
  requestAnimationFrame(()=>el.classList.add('show'));
  setTimeout(()=>{el.classList.remove('show'); setTimeout(()=>el.remove(),300)},2600);
}
function friendlyError(msg, status){
  const m=String(msg||'');
  if(/DATABASE_ERROR|базы данных|postgres|relation .* does not exist|ECONN|neon/i.test(m) || status===503)
    return 'Ошибка базы данных. В Netlify → Database включите БД и выполните SQL-миграции из папки migrations (001–042).';
  if(/не найдено/i.test(m) && status===404) return 'Нет доступа или запись не найдена';
  if(/нет доступа/i.test(m)) return 'Нет доступа к животному';
  if(/unauthorized|вход/i.test(m)) return 'Нужно войти в аккаунт';
  if(/forbidden|403/i.test(m)) return 'Недостаточно прав для этого действия';
  if(/слишком много попыток/i.test(m)) return m;
  return m || 'Что-то пошло не так. Попробуйте ещё раз';
}
let _errorTelemetryBusy=false;
async function reportClientError(data={}){
  if(_errorTelemetryBusy)return;
  _errorTelemetryBusy=true;
  try{
    const payload={source:'client',message:String(data.message||'Unknown error').slice(0,1200),stack:String(data.stack||'').slice(0,5000),url:location.href.slice(0,1000),path:String(data.path||'').slice(0,500),method:String(data.method||'').slice(0,20),status:Number(data.status)||null,screen:String(data.screen||document.querySelector('#content h2')?.textContent||'').slice(0,120),metadata:data.metadata&&typeof data.metadata==='object'?data.metadata:{}};
    await fetch('/api/telemetry/errors',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),keepalive:true}).catch(()=>{});
  }finally{_errorTelemetryBusy=false}
}
const api=async(path,opt={})=>{
  const method=(opt.method||'GET').toUpperCase(), key=method+':'+path, now=Date.now();
  if(method==='GET'){
    const hit=apiCache.get(key);
    if(hit && now-hit.time<1500)return hit.data;
    const pending=apiPending.get(key);
    if(pending)return pending;
  }else{
    apiCache.clear();
  }
  const request=(async()=>{
    let r;
    try{ r=await fetch('/api/'+path,{credentials:'include',headers:{'content-type':'application/json',...(opt.headers||{})},...opt}); }
    catch(fetchErr){ reportClientError({message:fetchErr?.message||'Network error',stack:fetchErr?.stack,path:'/api/'+path,method,status:0}); throw fetchErr; }
    const d=await r.json().catch(()=>({}));
    if(!r.ok){ reportClientError({message:d.error||d.message||`Ошибка API (${r.status})`,path:'/api/'+path,method,status:r.status,metadata:{api_error:d.code||''}}); throw Error(friendlyError(d.error||d.message||`Ошибка API (${r.status})`, r.status)); }
    if(method==='GET')apiCache.set(key,{time:Date.now(),data:d});
    return d;
  })();
  if(method==='GET')apiPending.set(key,request);
  try{return await request}finally{if(method==='GET')apiPending.delete(key)}
};
