// Унифицированные справочники MOSTIK Inside: подсказки + «Другое…» + сбор пользовательских вариантов.
const SMART_FIELD_MAP={
 species:['animals','species'],subspecies:['animals','subspecies'],breed:['animals','breed'],sex:['animals','sex'],
 meal:['diet','meal'],meal_other:['diet','meal_other'],products_text:['diet','product'],offered:['diet','product'],appetite:['diet','appetite'],eaten:['diet','eaten'],not_eaten:['diet','not_eaten'],note:['diet','note'],
 medication_name:['vet','medication'],record_type:['vet','record_type'],dosage:['vet','dosage'],frequency:['vet','frequency'],route:['vet','route'],
 parameter:['labs','parameter'],unit:['labs','unit'],reference_min:['labs','reference_min'],reference_max:['labs','reference_max'],
 skill_id:['training','skill'],session_length:['training','duration'],ending_type:['training','ending_type'],internal_stimulus:['behavior','internal_stimulus'],external_stimulus:['behavior','external_stimulus'],
 behavior_category:['behavior','category'],behavior_action:['behavior','action'],state_signs:['behavior','state_signs'],interaction_target:['behavior','interaction_target'],
 category:['enrichment','category'],type:['enrichment','type'],goal:['enrichment','goal'],material:['enrichment','material'],
 housing_type:['housing','type'],equipment:['housing','equipment'],appointment_type:['vet','appointment_type'],test_type:['labs','test_type']
};
const SMART_SECTIONS=['diet','vet','labs','training','behavior','enrichment','housing','animals'];
function smartSectionFor(el){const key=el?.dataset?.smartField||el?.name;return SMART_FIELD_MAP[key]?.[0]||''}
function smartFieldFor(el){const key=el?.dataset?.smartField||el?.name;return SMART_FIELD_MAP[key]?.[1]||''}
function smartSpecies(){return state.animal?.species||document.querySelector('[name="species"]')?.value||''}
async function smartRemember(el,value){
  value=String(value||'').trim(); if(!value||value==='Другое…'||value==='__OTHER__')return;
  const section=smartSectionFor(el),field=smartFieldFor(el); if(!section||!field)return;
  try{await api('smart-dictionary',{method:'POST',body:JSON.stringify({section,field,value_text:value,species:smartSpecies(),subspecies:state.animal?.subspecies||'',animal_id:state.animal?.id||null,metadata:{source:'form',screen:document.querySelector('#content h2')?.textContent||''}})});}catch{}
}
async function smartLoad(el){
  const section=smartSectionFor(el),field=smartFieldFor(el); if(!section||!field)return [];
  try{const d=await api(`smart-dictionary?section=${encodeURIComponent(section)}&field=${encodeURIComponent(field)}&species=${encodeURIComponent(smartSpecies())}`);return d.values||[]}catch{return []}
}
function smartApplyPayload(form,payload){
  if(!payload)return;
  if(typeof payload==='string'){
    try{ payload=JSON.parse(payload); }catch{ return; }
  }
  if(typeof payload!=='object')return;
  for(const [k,v] of Object.entries(payload)){
    const el=form.elements?.namedItem?.(k) || form.querySelector?.(`[name="${CSS.escape(k)}"]`);
    if(!el || v==null)continue;
    if(typeof RadioNodeList!=='undefined' && el instanceof RadioNodeList){
      const want=String(v);
      [...el].forEach(r=>{ r.checked = String(r.value)===want; });
      continue;
    }
    if(el.type==='checkbox')el.checked=['on','true',true,1,'1'].includes(v);
    else el.value=String(v);
    try{ el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); }catch{}
  }
}
async function smartEnhanceForm(form){
  if(!form||form.dataset.smartEnhanced==='1')return;
  const els=[...form.querySelectorAll('input[name],select[name],textarea[name]')].filter(el=>SMART_FIELD_MAP[el.name] && !(el.closest('.animal-form') && ['species','subspecies'].includes(el.name)));
  if(!els.length)return;
  form.dataset.smartEnhanced='1';
  const section=smartSectionFor(els[0]);
  const bar=document.createElement('div');bar.className='smart-template-bar';bar.innerHTML=`<div><b>SMART-помощник</b><small>Шаблон заполняет только поля формы — всё можно изменить.</small></div><div class="smart-template-actions"><select class="smart-template-select"><option value="">Выбрать шаблон…</option></select><button type="button" class="secondary smart-apply-template">Применить</button><button type="button" class="secondary smart-save-template">Сохранить как шаблон</button></div>`;
  form.prepend(bar);
  const sel=bar.querySelector('.smart-template-select');
  try{const d=await api(`smart-templates?section=${encodeURIComponent(section)}&species=${encodeURIComponent(smartSpecies()||'')}`);(d.templates||[]).forEach(tpl=>{const o=document.createElement('option');o.value=tpl.id;o.textContent=`${tpl.name}${tpl.species?' · '+tpl.species:''}`;o.dataset.payload=typeof tpl.payload==='string'?tpl.payload:JSON.stringify(tpl.payload||{});sel.appendChild(o)})}catch(err){console.warn('smart-templates load',err)}
  bar.querySelector('.smart-apply-template').onclick=()=>{
    const o=sel.selectedOptions[0];
    if(!o?.value){ try{toast('Выберите шаблон','warn')}catch{}; return; }
    let payload=o.dataset.payload;
    try{ payload=typeof payload==='string'?JSON.parse(payload||'{}'):(payload||{}); }catch{ payload={}; }
    if(!payload||!Object.keys(payload).length){ try{toast('В шаблоне нет полей','warn')}catch{}; return; }
    smartApplyPayload(form,payload);
    try{toast('Шаблон применён','ok')}catch{};
  };
  bar.querySelector('.smart-save-template').onclick=async()=>{
    const name=prompt('Название шаблона');
    if(!name?.trim())return;
    const payload={};
    // Save all named fields on the form (not only SMART_FIELD_MAP), so шаблон реально заполняет форму
    for(const el of [...form.querySelectorAll('input[name],select[name],textarea[name]')]){
      if(!el.name || el.type==='file' || el.type==='hidden' && !el.value) continue;
      if(el.type==='checkbox') payload[el.name]=!!el.checked;
      else if(el.type==='radio'){ if(el.checked) payload[el.name]=el.value; }
      else if(el.value!=null && String(el.value).trim()!=='') payload[el.name]=el.value;
    }
    if(!Object.keys(payload).length){ try{toast('Заполните хотя бы одно поле формы','warn')}catch{alert('Заполните поля')}; return; }
    try{
      await api('smart-templates',{method:'POST',body:JSON.stringify({section,name:name.trim(),description:`Шаблон ${section}`,species:smartSpecies()||null,payload,visibility:'personal'})});
      try{toast('Шаблон сохранён','ok')}catch{};
      const d=await api(`smart-templates?section=${encodeURIComponent(section)}&species=${encodeURIComponent(smartSpecies()||'')}`);
      sel.innerHTML='<option value="">Выбрать шаблон…</option>';
      (d.templates||[]).forEach(tpl=>{
        const o=document.createElement('option');
        o.value=tpl.id;
        o.textContent=tpl.name+(tpl.species?' · '+tpl.species:'');
        const pl=typeof tpl.payload==='string'?tpl.payload:JSON.stringify(tpl.payload||{});
        o.dataset.payload=pl;
        sel.appendChild(o);
      });
    }catch(e){ try{toast(e.message||'Не удалось сохранить шаблон','warn')}catch{alert(e.message)} }
  };
  for(const el of els){
    el.dataset.smartField=el.name;
    const listId=`smart-${section}-${smartFieldFor(el)}-${Math.random().toString(36).slice(2)}`;
    if(el.tagName==='INPUT' || el.tagName==='TEXTAREA'){
      const dl=document.createElement('datalist');dl.id=listId;el.setAttribute('list',listId);el.parentNode?.appendChild(dl);
      const refill=async()=>{dl.innerHTML='';const seen=new Set();const add=v=>{const x=String(v||'').trim();if(!x||seen.has(x.toLocaleLowerCase('ru-RU')))return;seen.add(x.toLocaleLowerCase('ru-RU'));const o=document.createElement('option');o.value=x;dl.appendChild(o)};try{(await smartLoad(el)).forEach(v=>add(v.value_text))}catch{};if(el.name==='species'){(state.animalCatalog||[]).forEach(v=>add(v.species))}if(el.name==='subspecies'){const sp=smartSpecies().toLocaleLowerCase('ru-RU');(state.animalCatalog||[]).filter(v=>String(v.species||'').toLocaleLowerCase('ru-RU')===sp).flatMap(v=>v.subspecies||[]).forEach(add)}};
      await refill();
      const other=document.createElement('button');other.type='button';other.className='secondary smart-other';other.textContent='Другое…';other.style.marginTop='6px';el.parentNode?.appendChild(other);
      other.onclick=()=>{const v=prompt(`Введите свой вариант для «${el.name}»`);if(v?.trim()){el.value=v.trim();smartRemember(el,v);el.dispatchEvent(new Event('change',{bubbles:true}))}};
      el.addEventListener('focus',()=>refill());el.addEventListener('input',()=>{if(el.value.length>=1)refill()});el.addEventListener('change',()=>{smartRemember(el,el.value);refill()});
    }else if(el.tagName==='SELECT'){
      const opts=await smartLoad(el);opts.forEach(v=>{if(![...el.options].some(o=>o.value===v.value_text)){const o=document.createElement('option');o.value=v.value_text;o.textContent=v.value_text;el.appendChild(o)}});
      const other=document.createElement('option');other.value='__OTHER__';other.textContent='Другое…';el.appendChild(other);
      el.addEventListener('change',()=>{if(el.value==='__OTHER__'){const v=prompt(`Введите свой вариант для «${el.name}»`);if(v?.trim()){const o=document.createElement('option');o.value=v.trim();o.textContent=v.trim();el.insertBefore(o,other);el.value=v.trim();smartRemember(el,v)}}else smartRemember(el,el.value)});
    }
  }
}
function enhanceSmartFields(root=document){root.querySelectorAll?.('form').forEach(f=>smartEnhanceForm(f));}
function smartTemplates(c){
 c.innerHTML=`<div class="card"><div class="top"><div><h2>Шаблоны MOSTIK</h2><p class="muted">Единые шаблоны для рациона, ветеринарии, анализов, тренировок, поведения и обогащения. Значения остаются редактируемыми.</p></div><button id="refreshSmartTemplates">Обновить</button></div><div id="smartTemplatesBody"><p class="muted">Загружаю…</p></div></div><div class="card" style="margin-top:18px"><h3>MOSTIK Inside · пользовательские варианты</h3><p class="muted">MOSTIK отслеживает «Другое…», частоту использования и вид животного. Администратор может перевести вариант в официальный справочник.</p><div id="smartCustomStats"><p class="muted">Загружаю…</p></div></div>`;
 const load=async()=>{try{const d=await api('smart-templates');document.querySelector('#smartTemplatesBody').innerHTML=SMART_SECTIONS.map(sec=>{const rows=(d.templates||[]).filter(x=>x.section===sec);return `<section class="card"><h3>${esc(sec)}</h3>${rows.length?rows.map(t=>`<article class="timeline"><b>${esc(t.name)}</b>${t.species?`<small>Вид: ${esc(t.species)}</small>`:''}<p>${esc(t.description||'')}</p><button type="button" class="danger delete-smart-template" data-id="${t.id}">Удалить</button></article>`).join(''):'<p class="muted">Шаблонов нет.</p>'}</section>`}).join('');document.querySelectorAll('.delete-smart-template').forEach(b=>b.onclick=async()=>{if(confirm('Удалить шаблон?')){await api(`smart-templates/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});load()}});if(state.user.effective_role==='admin'){const x=await api('admin/smart-dictionary?days=90');document.querySelector('#smartCustomStats').innerHTML=(x.values||[]).map(v=>`<div class="summary-row"><span>${esc(v.value_text)} · ${esc(v.section)}/${esc(v.field)}${v.species?' · '+esc(v.species):''}</span><b>${v.usage_count} · ${esc(v.status)}</b><button class="secondary smart-status" data-id="${v.id}" data-status="${v.status==='official'?'unverified':'official'}">${v.status==='official'?'Снять официальный':'Сделать официальным'}</button></div>`).join('')||'<p class="muted">Пользовательских вариантов пока нет.</p>';document.querySelectorAll('.smart-status').forEach(b=>b.onclick=async()=>{await api('admin/smart-dictionary/status',{method:'PUT',body:JSON.stringify({id:b.dataset.id,status:b.dataset.status})});load()})}else document.querySelector('#smartCustomStats').innerHTML='<p class="muted">Статистика проверки доступна администратору.</p>'}catch(e){document.querySelector('#smartTemplatesBody').innerHTML=`<p class="error">${esc(e.message)}</p>`}};
 document.querySelector('#refreshSmartTemplates').onclick=load;load();
}

const HEALTH_PRESETS=[
 {type:'hearing',title:'Нарушение слуха'},
 {type:'vision',title:'Нарушение зрения'},
 {type:'voice',title:'Нарушение голосовой функции'},
 {type:'allergy',title:'Аллергия'},
 {type:'diabetes',title:'Диабет'},
 {type:'epilepsy',title:'Эпилепсия / судороги'},
 {type:'heart',title:'Сердечно-сосудистое заболевание'},
 {type:'respiratory',title:'Заболевание дыхательной системы'},
 {type:'kidney',title:'Заболевание почек'},
 {type:'liver',title:'Заболевание печени'},
 {type:'mobility',title:'Ограничение подвижности'},
 {type:'chronic',title:'Хроническое заболевание'},
 {type:'medication',title:'Постоянный приём лекарств'},
 {type:'diet',title:'Диетические ограничения'},
 {type:'other',title:'Другое'}
];
function healthSeverityLabel(v){return ({critical:'Критично',important:'Важно',info:'Информация'})[v]||'Важно'}
function healthStatusLabel(v){return ({confirmed:'Подтверждено врачом',suspected:'Подозрение',observation:'Наблюдение'})[v]||'Наблюдение'}
function animalStatusLabel(v){return ({normal:'Обычное состояние',attention:'Требует внимания',critical:'Критично'})[v]||'Обычное состояние'}
function animalStatusIcon(v){return ({normal:'<span class="ui-emoji" aria-hidden="true">●</span>',attention:'<span class="ui-emoji" aria-hidden="true">●</span>',critical:'<span class="ui-emoji" aria-hidden="true">●</span>'})[v]||'<span class="ui-emoji" aria-hidden="true">●</span>'}
function animalStatusClass(v){return ({normal:'status-normal',attention:'status-attention',critical:'status-critical'})[v]||'status-normal'}
function animalContextBar(){
 const a=state.animal;
 if(!a){return `<div class="animal-context all-context"><div><b><span class="ui-emoji" aria-hidden="true">◆</span> Все животные</b><span class="muted"> · ${state.animals.length} доступно</span></div><button class="secondary" type="button" id="openAllAnimalsContext">Открыть список</button></div>`}
 return `<div class="animal-context"><div class="animal-context-main">${photoMarkup(a,'animal-context-avatar')}<div><strong>${esc(a.name)}</strong><small>${esc(a.species||'')}${a.breed?' · '+esc(a.breed):''} · ID <button type="button" class="linkish copy-ctx-id" data-id="${esc(a.id)}" title="Код животного для семьи, ветеринара или тренера">${esc(a.id)}</button></small></div></div><div class="animal-context-actions"><span class="animal-status-pill ${animalStatusClass(a.status)}">${animalStatusIcon(a.status)} ${esc(animalStatusLabel(a.status))}</span><button type="button" class="secondary" id="openAnimalProfile">Профиль</button></div></div>`
}
function bindAnimalContext(){
 document.querySelector('#openAnimalProfile')?.addEventListener('click',()=>view('home'));
 document.querySelector('#openAllAnimalsContext')?.addEventListener('click',()=>view('animals'));
 document.querySelectorAll('.copy-ctx-id').forEach(b=>b.addEventListener('click',async e=>{
   e.preventDefault(); e.stopPropagation();
   const ok=await copyText(b.dataset.id);
   const prev=b.textContent;
   b.textContent=ok?'скопировано':'ошибка';
   setTimeout(()=>b.textContent=prev,1200);
 }));
}
async function loadGuidance(){
 try { const d=await api(`guidance${state.animal?`?animal_id=${encodeURIComponent(state.animal.id)}`:''}`); return d.actions||[]; } catch { return []; }
}
function renderGuidance(c, actions){
 const rank={critical:'Критично',high:'Высокая важность',medium:'Важно',low:'Информация'};
 const overdue=actions.filter(x=>x.priority==='critical'||x.priority==='high');
 const filter=state.homeTaskFilter||'all';
 if(!actions.length) return `<div class="card guidance-card"><div class="top"><div><h3><span class="ui-emoji" aria-hidden="true">◆</span> Что делать сейчас</h3><p class="muted">На данный момент обязательных действий нет.</p></div></div><div class="notice">✓ Всё основное на сегодня под контролем.</div></div>`;
 const shown=filter==='overdue'?overdue:actions;
 return `<div class="card guidance-card"><div class="top"><div><h3><span class="ui-emoji" aria-hidden="true">◆</span> Что делать сейчас</h3><p class="muted">MOSTIK расставил задачи по важности и времени.</p></div><span class="badge" id="guidanceCount">${shown.length} задач</span></div>
 <div class="home-task-filters">
  <button type="button" class="chip-filter ${filter==='all'?'active':''}" data-home-filter="all">Все сегодня (${actions.length})</button>
  <button type="button" class="chip-filter ${filter==='overdue'?'active':''}" data-home-filter="overdue">Просроченное / срочное (${overdue.length})</button>
 </div>
 <div class="guidance-list">${shown.slice(0,12).map(x=>`<article class="guidance-item ${esc(x.priority)}" data-priority="${esc(x.priority)}"><div class="guidance-icon">${rank[x.priority]||'●'}</div><div class="guidance-main"><strong>${esc(x.title)}</strong><small>${esc(x.animal_name||'')}${x.detail?' · '+esc(x.detail):''}</small></div><button class="secondary guidance-open" data-animal-id="${esc(x.animal_id)}" data-view-target="${esc(x.view||'home')}">Открыть</button></article>`).join('')||'<p class="muted">По выбранному фильтру задач нет.</p>'}</div></div>`
}
function healthBanner(){
 const a=state.animal, list=a?.health_features||[]; if(!list.length)return '';
 const critical=list.filter(x=>x.severity==='critical'), important=list.filter(x=>x.severity!=='info');
 return `<div class="health-banner ${critical.length?'critical':''}" role="alert"><div class="health-banner-head"><div><span class="health-kicker"><span class="ui-emoji" aria-hidden="true">✚</span> ОСОБЕННОСТИ ЗДОРОВЬЯ</span><strong>${critical.length?'Требует особого внимания':'Важно учитывать в работе'}</strong></div><button type="button" class="secondary" id="openHealthFeatures">Подробнее</button></div><div class="health-chips">${list.map(x=>`<span class="health-chip ${x.severity==='critical'?'critical':x.severity==='important'?'important':''}"><b>${esc(x.title)}</b><small>${esc(healthSeverityLabel(x.severity))}</small></span>`).join('')}</div><div class="health-note">Эти сведения видят специалисты, у которых есть доступ к ${esc(a.name)}. Проверяйте предупреждения перед тренировкой, процедурой и наблюдением.</div></div>`;
}
function render(){
 applySettings();
 if(!state.user){renderAuth();return}
 const r=state.user.effective_role||state.user.role;
 // Навигация по ролям (что видит пользователь)
 // Одинаковый порядок разделов для всех ролей
 let nav='<button data-view="home">Главная</button>'
   +'<button data-view="care">Забота</button>'
   +'<button data-view="vet">Ветеринария</button>'
   +'<button data-view="training">Тренировка</button>'
   +'<button data-view="analytics">Аналитика</button>'
   +'<button data-view="calendar">Календарь</button>'
   +'<button data-view="settings">Настройки</button>'
   +'<button id="logoutNavBtn" class="more-nav-btn danger">Выйти</button>';
 app.innerHTML=`<aside><img src="${currentLogoSrc()}" class="side-logo" alt="MOSTIK"><b>MOSTIK</b>${nav}</aside><main class="main"><header><div><span class="muted">${esc(roleName(r))}</span><h1>${esc(state.user.display_name)}</h1></div><div class="header-controls"><button type="button" class="secondary header-cmdk" id="openCmdPalette" title="Ctrl/Cmd+K">⌕</button>${state.animals.length?`<label class="animal-switcher"><span class="muted">Животное</span><select id="animal"><option value="__ALL__" ${!state.animal?'selected':''}>Все животные</option>${state.animals.map(a=>`<option value="${esc(a.id)}" ${state.animal?.id===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`:''}<button type="button" class="secondary header-journal-btn" id="openJournal" title="Журнал событий">Журнал</button>${(()=>{const real=[...new Set([...userRoles(),state.user.role].filter(Boolean))];const opts=real.map(x=>`<option value="${x}" ${x===r?'selected':''}>${roleName(x)}</option>`);return (real.length>1||state.user.role==='admin')?`<label class="role-switcher"><span class="muted">Роль</span><select id="activeRole">${opts.join('')}</select></label>`:''})()}</div></header>${healthBanner()}<section id="content"></section></main>`;
 bindShell();view(defaultViewForRole());
 setTimeout(()=>enhanceSmartFields(document),120);
 setTimeout(()=>maybeStartOnboarding(),180);
}
async function renderAuth(){
 applySettings();
 let setup=false;try{setup=(await api('auth/status')).setup_required}catch{}
 const params=new URLSearchParams(location.search); const resetToken=params.get('reset');
 if(resetToken)return renderResetPassword(resetToken);
 const roleOptions=[['owner','Владелец'],['trainer','Тренер'],['vet','Ветеринар'],['keeper','Кипер']];
 app.innerHTML=`<main class="auth"><div class="card auth-card"><img src="${currentLogoSrc()}" class="logo" alt="MOSTIK"><h1>MOSTIK</h1><p class="muted">Единое пространство для владельца, тренера, ветеринара и кипера</p><div class="tabs"><button class="tab ${state.authMode==='login'?'active':''}" data-a="login">Вход</button><button class="tab ${state.authMode==='register'?'active':''}" data-a="register">Регистрация</button></div><div class="notice">${state.authMode==='register'?(setup?'Это первый аккаунт в системе: для запуска MOSTIK он будет создан как администратор. После этого новые пользователи смогут выбрать свою роль.':'Выберите свою роль. Администратор сможет изменить доступ к животным и права позже.'):'Введите email и пароль.'}</div><form id="auth"><input name="display_name" placeholder="Имя и фамилия" autocomplete="name" ${state.authMode==='register'?'required':'hidden'}><input name="email" type="email" placeholder="Email" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" inputmode="email" required><div class="password-wrap"><input id="authPassword" name="password" type="password" placeholder="Пароль (минимум 6 символов)" autocomplete="${state.authMode==='register'?'new-password':'current-password'}" autocapitalize="none" autocorrect="off" spellcheck="false" minlength="6" required><button type="button" class="password-toggle secondary" data-target="authPassword" aria-label="Показать пароль"></button></div>${state.authMode==='register'?`<label class="auth-role">Ваша роль<select name="role">${roleOptions.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label>`:''}<button>${state.authMode==='register'?'Зарегистрироваться':'Войти'}</button></form>${state.authMode==='login'?'<button type="button" id="forgotPassword" class="link-btn">Забыли пароль?</button>':''}<p id="msg" class="error"></p></div></main>`;
 document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{
  const form=document.querySelector('#auth');
  if(form){
    const fd=new FormData(form);
    state.authDraft={
      display_name:fd.get('display_name')||state.authDraft?.display_name||'',
      email:fd.get('email')||state.authDraft?.email||'',
      password:fd.get('password')||state.authDraft?.password||'',
      role:fd.get('role')||state.authDraft?.role||'owner'
    };
  }
  state.authMode=b.dataset.a;
  renderAuth();
});
 document.querySelectorAll('.password-toggle').forEach(b=>b.onclick=()=>togglePassword(b));
 document.querySelector('#forgotPassword')?.addEventListener('click',renderForgotPassword);
 // restore draft values
 (function(){
   const d=state.authDraft||{};
   const form=document.querySelector('#auth'); if(!form) return;
   if(d.display_name && form.display_name) form.display_name.value=d.display_name;
   if(d.email && form.email) form.email.value=d.email;
   if(d.password && form.password) form.password.value=d.password;
   if(d.role && form.role) form.role.value=d.role;
 })();
 document.querySelector('#auth').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));
 state.authDraft={display_name:b.display_name||'',email:b.email||'',password:b.password||'',role:b.role||'owner'};try{const d=await api(state.authMode==='register'?'auth/register':'auth/login',{method:'POST',body:JSON.stringify(b)});if(state.authMode==='register'&&d.recovery_code){app.innerHTML=`<main class="auth"><div class="card auth-card"><img src="${currentLogoSrc()}" class="logo" alt="MOSTIK"><h1>Аккаунт создан</h1><p class="muted">Сохраните этот код восстановления. Он понадобится, если вы забудете пароль.</p><div class="recovery-code"><b>${esc(d.recovery_code)}</b></div><div class="notice"><b>Важно:</b> это не пароль. Никому не передавайте код. После восстановления пароля код автоматически заменяется.</div><button id="continueAfterRegister">Продолжить в MOSTIK</button></div></main>`;document.querySelector('#continueAfterRegister').onclick=()=>location.reload();}else location.reload()}catch(x){document.querySelector('#msg').textContent=x.message}};
}
function togglePassword(b){const el=document.getElementById(b.dataset.target); if(!el)return; el.type=el.type==='password'?'text':'password'; b.textContent=el.type==='password'?'':''}
function renderForgotPassword(){app.innerHTML=`<main class="auth"><div class="card auth-card"><img src="${currentLogoSrc()}" class="logo" alt="MOSTIK"><h1>Восстановление пароля</h1><p class="muted">Бесплатный вариант без почты: используйте код восстановления, который MOSTIK показал после регистрации.</p><div class="notice"><b>Нет кода?</b> Попросите администратора выдать новый код восстановления.</div><form id="recoverForm"><input name="email" type="email" placeholder="Email" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" inputmode="email" required><input name="recovery_code" placeholder="Код восстановления" autocomplete="off" required><div class="password-wrap"><input id="recoverNewPass" name="password" type="password" minlength="6" placeholder="Новый пароль" required><button type="button" class="password-toggle secondary" data-target="recoverNewPass" aria-label="Показать пароль"></button></div><button>Сменить пароль</button><button type="button" id="backLogin" class="secondary">Вернуться ко входу</button></form><p id="msg" class="error"></p></div></main>`;document.querySelector('#backLogin').onclick=()=>renderAuth();document.querySelectorAll('.password-toggle').forEach(b=>b.onclick=()=>togglePassword(b));document.querySelector('#recoverForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{const d=await api('auth/recover',{method:'POST',body:JSON.stringify(b)});document.querySelector('#msg').className='notice';document.querySelector('#msg').innerHTML=`${esc(d.message)}<div class="recovery-code"><b>${esc(d.recovery_code)}</b></div><p class="muted">Сохраните новый код восстановления.</p>`;e.target.reset()}catch(x){document.querySelector('#msg').className='error';document.querySelector('#msg').textContent=x.message}}}
function renderResetPassword(token){app.innerHTML=`<main class="auth"><div class="card auth-card"><img src="${currentLogoSrc()}" class="logo" alt="MOSTIK"><h1>Новый пароль</h1><p class="muted">Придумайте новый пароль минимум из 6 символов.</p><form id="resetForm"><div class="password-wrap"><input id="newPass" name="password" type="password" minlength="6" placeholder="Новый пароль" required><button type="button" class="password-toggle secondary" data-target="newPass"></button></div><div class="password-wrap"><input id="newPass2" name="password2" type="password" minlength="6" placeholder="Повторите пароль" required><button type="button" class="password-toggle secondary" data-target="newPass2"></button></div><button>Сменить пароль</button></form><p id="msg" class="error"></p></div></main>`;document.querySelectorAll('.password-toggle').forEach(b=>b.onclick=()=>togglePassword(b));document.querySelector('#resetForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.password!==b.password2){document.querySelector('#msg').textContent='Пароли не совпадают';return}try{const d=await api('auth/reset-password',{method:'POST',body:JSON.stringify({token,password:b.password})});document.querySelector('#msg').className='notice';document.querySelector('#msg').textContent=d.message;history.replaceState({},'',location.pathname);setTimeout(()=>renderAuth(),1400)}catch(x){document.querySelector('#msg').textContent=x.message}}}

function getSettings(){try{return JSON.parse(localStorage.getItem('mostik_settings')||'{}')}catch{return {}}}
function saveSettings(x){localStorage.setItem('mostik_settings',JSON.stringify(x));applySettings()}
const ROLE_THEME_DEFAULTS={admin:'classic',owner:'classic',trainer:'lion',keeper:'elephant',vet:'serpent'};
const SETTINGS_THEMES={
  classic:'Классика — стандарт',
  bull:'Бык — сила',
  horizon:'Горизонт — тепло',
  serpent:'Змей — глубина',
  lion:'Лев — энергия',
  eagle:'Орёл — небо',
  elephant:'Слон — мудрость',
  fox:'Лиса — грация',
  nest:'Гнездо — уют',
  owl:'Сова — знание',
  cyber:'Кибер — неон',
  cosmos:'Космос — ночь'
};
const SETTINGS_MODES={auto:'Авто день/ночь',light:'Всегда светлая',dark:'Всегда тёмная'};
const SETTINGS_RADIUS={
  none:'Без скругления — современно',
  sm:'Небольшое — 6px',
  md:'Среднее — 12px',
  lg:'Крупное — 18px'
};
function currentRole(){return state.user?.effective_role||state.user?.role||'owner'}
function applySettings(){
  const role=currentRole();
  const existing=getSettings();
  let scheme=existing.scheme||ROLE_THEME_DEFAULTS[role]||'classic';
  // Migrate legacy theme keys to new logo themes
  const LEGACY_THEME_MAP={sage:'classic',forest:'elephant',sand:'horizon',clinical:'serpent',midnight:'cosmos',ocean:'eagle',lavender:'fox',sunrise:'lion'};
  if(LEGACY_THEME_MAP[scheme]) scheme=LEGACY_THEME_MAP[scheme];
  if(!THEME_LOGO_SRCS[scheme]) scheme='classic';
  let radius=existing.radius||'none';
  if(!SETTINGS_RADIUS[radius]) radius='none';
  const s={scheme,mode:existing.mode||'auto',radius,hints:existing.hints||'yes',...existing,scheme,radius};
  document.documentElement.dataset.theme=s.scheme;
  document.documentElement.dataset.mode=s.mode;
  document.documentElement.dataset.radius=s.radius;
  document.documentElement.dataset.role=role;
  document.documentElement.style.colorScheme=s.mode==='dark'?'dark':s.mode==='light'?'light':'light dark';
  if(s.default_animal){const a=state.animals.find(x=>x.name===s.default_animal);if(a)state.animal=a}
  document.body.classList.toggle('no-hints',s.hints==='no');
  try{ refreshLogos(); }catch(_){}
}
function settings(c){
 if(!c) return;
 const role=currentRole();
 const s={scheme:ROLE_THEME_DEFAULTS[role]||'classic',mode:'auto',radius:'none',default_animal:'',date_format:'DD.MM.YYYY',hints:'yes',session_length:'12h',access_mode:'lan',...getSettings()};
 c.innerHTML=`<div class="top"><div><h2>Настройки</h2><p class="muted">Оформление можно менять сразу. Подборки тем адаптированы под роль, но любую тему можно выбрать вручную.</p></div></div>
 <div class="card theme-role-banner"><strong>Роль: ${esc(roleName(role))}</strong><span class="muted">Рекомендуемая тема: ${esc(SETTINGS_THEMES[ROLE_THEME_DEFAULTS[role]]||SETTINGS_THEMES.classic)}</span></div>
 
 <div class="card settings-card settings-tools-card"><h3>Инструменты</h3><p class="muted">Разделы, которые раньше были в главном меню.</p>
 <div class="settings-tools-grid">
  <button type="button" class="secondary settings-tool-btn" data-open-view="smart-templates">Шаблоны</button>
  ${['admin'].includes(role)?`<button type="button" class="secondary settings-tool-btn" data-open-view="admin">Админ</button><button type="button" class="secondary settings-tool-btn" data-open-view="admin-errors">Ошибки</button>`:''}
 </div></div>
<div class="grid settings-grid">
 <div class="card settings-card"><h3>Оформление</h3><label>Тема MOSTIK<select name="scheme" id="themeScheme">${Object.entries(SETTINGS_THEMES).map(([k,v])=>`<option value="${k}" ${k===s.scheme?'selected':''}>${v}</option>`).join('')}</select></label><div class="theme-swatches">${Object.entries(SETTINGS_THEMES).map(([k,v])=>`<button type="button" class="theme-swatch theme-swatch-${k} ${k===s.scheme?'active':''}" data-theme-choice="${k}" title="${esc(v)}"><img class="theme-swatch-logo" src="${THEME_LOGO_SRCS[k]||''}" alt="" width="36" height="36"><b>${esc(v.split(' — ')[0])}</b></button>`).join('')}</div><label>Режим интерфейса<select name="mode" id="themeMode">${Object.entries(SETTINGS_MODES).map(([k,v])=>`<option value="${k}" ${k===s.mode?'selected':''}>${v}</option>`).join('')}</select></label>
<label>Скругление элементов<select name="radius" id="themeRadius">${Object.entries(SETTINGS_RADIUS).map(([k,v])=>`<option value="${k}" ${(s.radius||'none')===k?'selected':''}>${v}</option>`).join('')}</select></label>
<div class="radius-preview" aria-hidden="true">
  <span class="radius-preview-card">Карточка</span>
  <span class="radius-preview-btn">Кнопка</span>
  <span class="radius-preview-chip">Статус</span>
</div>
<p class="muted">Скругление применяется к карточкам, кнопкам, полям, модалкам, вкладкам и чипам. Логотипы и аватары остаются круглыми.</p>
<p class="muted">Изменения темы применяются сразу, без перезагрузки.</p></div>
 <div class="card settings-card"><h3>Рабочий контекст</h3><label>Животное по умолчанию<select name="default_animal"><option value="">Автоматически</option>${(state.animals||[]).map(a=>`<option value="${esc(a.name)}" ${a.name===s.default_animal?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Формат даты<select name="date_format"><option value="DD.MM.YYYY" ${s.date_format==='DD.MM.YYYY'?'selected':''}>ДД.ММ.ГГГГ</option><option value="YYYY-MM-DD" ${s.date_format==='YYYY-MM-DD'?'selected':''}>ГГГГ-ММ-ДД</option></select></label><label>Показывать подсказки<select name="hints"><option value="yes" ${s.hints==='yes'?'selected':''}>Да</option><option value="no" ${s.hints==='no'?'selected':''}>Нет</option></select></label></div>
 <div class="card settings-card"><h3>Сессия и доступ</h3><label>Срок сессии<select name="session_length"><option value="12h" ${s.session_length==='12h'?'selected':''}>12 часов</option><option value="4h" ${s.session_length==='4h'?'selected':''}>4 часа</option><option value="1h" ${s.session_length==='1h'?'selected':''}>1 час</option></select></label><label>Режим доступа<select name="access_mode"><option value="lan" ${s.access_mode==='lan'?'selected':''}>Локальная сеть / доверенные устройства</option><option value="local" ${s.access_mode==='local'?'selected':''}>Только это устройство</option></select></label><p class="muted">Параметр доступа сохраняется как настройка интерфейса; фактическое сетевое ограничение задаётся сервером Netlify.</p></div>
 <div class="card settings-card"><h3>Данные и резервные копии</h3><div class="actions"><button class="btn" id="exportJson">Экспорт JSON</button><button class="btn secondary" id="exportCsv">Экспорт Excel/CSV</button><button class="btn secondary" id="printPdf">Печать / PDF</button><button class="btn secondary" id="backupSettings">Бэкап настроек</button></div><label>Импорт настроек JSON<input id="importSettings" type="file" accept=".json,application/json"></label><p class="muted">Экспорт сохраняет настройки устройства и доступные данные выбранного животного.</p></div>
 <div class="card settings-card"><h3>Обучение</h3><p class="muted">Повторите короткое знакомство с интерфейсом.</p><div class="actions"><button class="btn secondary" id="replayOnboarding">▶ Пройти обучение ещё раз</button></div><button class="secondary" id="resetSettings">Сбросить настройки</button></div>
 <div class="card settings-card"><h3>Приложение и управление</h3><div class="actions">${role==='admin'?'<button type="button" class="btn secondary" id="goInsight">MOSTIK Insight</button><button type="button" class="btn secondary" id="goAdmin">Администрирование</button>':''}<button type="button" class="btn secondary" id="settingsInstall">Установить приложение</button></div></div></div>
 <div class="settings-save"><button class="btn" id="saveSettings">Сохранить рабочие настройки</button></div>`;
 const setField=(name,value)=>{const f=c.querySelector(`[name="${name}"]`);if(f)f.value=value};
 const liveSaveTheme=()=>{const cur={...getSettings(),scheme:c.querySelector('[name="scheme"]').value,mode:c.querySelector('[name="mode"]').value,radius:c.querySelector('[name="radius"]')?.value||'none'};saveSettings(cur);applySettings();c.querySelectorAll('[data-theme-choice]').forEach(b=>b.classList.toggle('active',b.dataset.themeChoice===cur.scheme));};
 c.querySelectorAll('.settings-tool-btn[data-open-view]').forEach(b=>{
   b.addEventListener('click', (e)=>{
     e.preventDefault();
     const v=b.dataset.openView;
     if(v) view(v);
   });
 });
 c.querySelector('#themeScheme').addEventListener('change',liveSaveTheme);
 c.querySelector('#themeMode').addEventListener('change',liveSaveTheme);
 c.querySelector('#themeRadius')?.addEventListener('change',liveSaveTheme);
 c.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{setField('scheme',b.dataset.themeChoice);liveSaveTheme()});
 c.querySelector('#saveSettings').onclick=()=>{const n={...getSettings()};c.querySelectorAll('select[name]').forEach(x=>n[x.name]=x.value);saveSettings(n);applySettings();alert('Настройки сохранены');render();};
 c.querySelector('#resetSettings').onclick=()=>{if(confirm('Сбросить все настройки MOSTIK на этом устройстве?')){localStorage.removeItem('mostik_settings');applySettings();render()}};
 c.querySelector('#exportJson').onclick=()=>downloadText('mostik_backup.json',JSON.stringify({version:'5.0.6',exported_at:new Date().toISOString(),settings:getSettings(),animal:state.animal,skills:state.skills,today:state.today||null},null,2),'application/json');
 c.querySelector('#exportCsv').onclick=()=>downloadText('mostik_export.csv','MOSTIK\nЖивотное,Вид,Порода\n'+[state.animal?.name,state.animal?.species,state.animal?.breed].map(csv).join(',')+'\n\nНастройка,Значение\n'+Object.entries(getSettings()).map(([k,v])=>`${csv(k)},${csv(v)}`).join('\n'),'text/csv;charset=utf-8');
 c.querySelector('#printPdf').onclick=()=>window.print();
 c.querySelector('#backupSettings').onclick=()=>downloadText('mostik_settings_backup.json',JSON.stringify({settings:getSettings(),created_at:new Date().toISOString()},null,2),'application/json');
 c.querySelector('#importSettings').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);saveSettings(d.settings||d);applySettings();alert('Настройки импортированы');render()}catch{alert('Не удалось импортировать JSON')}};r.readAsText(f)};
 c.querySelector('#replayOnboarding')?.addEventListener('click',()=>startOnboarding(true));
 c.querySelector('#goInsight')?.addEventListener('click',()=>view('insight'));
 c.querySelector('#goAdmin')?.addEventListener('click',()=>view('admin'));
 c.querySelector('#settingsInstall')?.addEventListener('click',async()=>{const ok=await installMostik();if(!ok)alert('Если автоматическая установка недоступна, откройте меню браузера и выберите «Добавить на главный экран».')});
}
function csv(v){return `"${String(v??'').replaceAll('"','""')}"`}
function downloadText(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function onboardingStorageKey(){
  const id=state.user?.id||state.user?.email||'anon';
  const role=state.user?.effective_role||state.user?.role||'owner';
  return 'mostik_onboarding_done:'+id+':'+role;
}
function maybeStartOnboarding(){if(localStorage.getItem(onboardingStorageKey())!=='1')startOnboarding(false)}

/** Shared step builders — targets match real menu labels per role */
function onbNav(n, view, title, text){
  return {
    id:'nav-'+view,
    title:n+'. '+title,
    text:text,
    target:'aside [data-view="'+view+'"]',
    position:'right', action:'click',
    match:(e)=>!!e.target?.closest?.('aside [data-view="'+view+'"]'),
    done:()=>!!document.querySelector('aside [data-view="'+view+'"].active')
  };
}
function onbWelcome(title, text){
  return {id:'welcome', title:title, text:text, target:null, position:'center', action:'none'};
}
function onbDone(text){
  return {id:'done', title:'Обучение завершено', text:text||'Можно работать самостоятельно. Повтор — в Настройках.', target:null, position:'center', action:'none'};
}
function onbCreateAnimalSteps(startN){
  let n=startN;
  return [
    {
      id:'open-add',
      title:(n++)+'. Добавить животное',
      text:'Нажмите «＋ Добавить животное» (или «＋ Новое животное», если список пуст).',
      target:'#openAddAnimal, #openAddAnimalEmpty', position:'bottom', action:'click',
      match:(e)=>!!e.target?.closest?.('#openAddAnimal, #openAddAnimalEmpty, .add-animal-btn'),
      done:()=>{const m=document.querySelector('#animalAddModal'); return m && !m.hidden}
    },
    {
      id:'choose-create',
      title:(n++)+'. Новое животное',
      text:'Выберите «Новое животное», чтобы создать карточку.',
      target:'#chooseCreateAnimal', position:'bottom', action:'click',
      match:(e)=>!!e.target?.closest?.('#chooseCreateAnimal, [data-add-choice="create"]'),
      done:()=>{const p=document.querySelector('#createAnimalPanel'); return p && !p.hidden}
    },
    {
      id:'fill-name',
      title:(n++)+'. Имя',
      text:'Введите имя в поле «Имя животного».',
      target:'#animalAdd input[name="name"]', position:'bottom', action:'input',
      match:(e)=>{const el=e.target?.closest?.('#animalAdd input[name="name"]'); return !!(el && String(el.value||'').trim().length>=2)},
      done:()=>{const el=document.querySelector('#animalAdd input[name="name"]'); return !!(el && String(el.value||'').trim().length>=2)}
    },
    {
      id:'fill-species',
      title:(n++)+'. Вид',
      text:'Укажите вид. Можно выбрать из подсказок.',
      target:'#animalAdd input[name="species"]', position:'bottom', action:'input',
      match:(e)=>{const el=e.target?.closest?.('#animalAdd input[name="species"]'); return !!(el && String(el.value||'').trim().length>=2)},
      done:()=>{const el=document.querySelector('#animalAdd input[name="species"]'); return !!(el && String(el.value||'').trim().length>=2)}
    },
    {
      id:'save-animal',
      pollDone:true,
      title:(n++)+'. Сохранить',
      text:'Нажмите «Создать животное». После сохранения нажмите «Далее».',
      target:'#createAnimalSubmit, #animalAdd button.primary', position:'top', action:'click',
      match:(e)=>!!e.target?.closest?.('#createAnimalSubmit, #animalAdd button.primary, #animalAdd button[type="submit"]'),
      done:()=>{const m=document.querySelector('#animalAddModal'); return (!m||m.hidden) && (state.animals||[]).length>0}
    },
    {
      id:'pick-animal',
      title:(n++)+'. Выберите животное',
      text:'Выберите животное в списке сверху — MOSTIK будет подставлять его в формы.',
      target:'#animal', position:'bottom', action:'change',
      match:(e)=>e.target?.id==='animal' && e.target.value && e.target.value!=='__ALL__',
      done:()=>!!state.animal
    }
  ];
}
function onbJoinAnimalSteps(startN){
  let n=startN;
  return [
    {
      id:'open-add-join',
      title:(n++)+'. Добавить животное',
      text:'Нажмите «＋ Добавить животное». Можно создать карточку или подключиться по ID.',
      target:'#openAddAnimal, #openAddAnimalEmpty', position:'bottom', action:'click',
      match:(e)=>!!e.target?.closest?.('#openAddAnimal, #openAddAnimalEmpty, .add-animal-btn'),
      done:()=>{const m=document.querySelector('#animalAddModal'); return m && !m.hidden}
    },
    {
      id:'choose-join',
      title:(n++)+'. Подключение по ID',
      text:'Если животное уже есть у владельца — выберите «У меня есть ID». Либо закройте окно и выберите животное сверху, если оно уже в списке.',
      target:'#chooseJoinAnimal, #chooseCreateAnimal', position:'bottom', action:'click',
      match:(e)=>!!e.target?.closest?.('#chooseJoinAnimal, #chooseCreateAnimal, [data-add-choice], #closeAddAnimal'),
      done:()=>true
    },
    {
      id:'pick-animal-join',
      title:(n++)+'. Рабочее животное',
      text:'Выберите животное в верхней панели «Животное».',
      target:'#animal', position:'bottom', action:'change',
      match:(e)=>e.target?.id==='animal' && e.target.value && e.target.value!=='__ALL__',
      done:()=>!!state.animal || (state.animals||[]).length>0
    }
  ];
}

function onboardingSteps(){
  const role=state.user?.effective_role||state.user?.role||'owner';
  if(role==='trainer') return onboardingStepsTrainer();
  if(role==='keeper') return onboardingStepsKeeper();
  if(role==='vet') return onboardingStepsVet();
  if(role==='admin') return onboardingStepsAdmin();
  return onboardingStepsOwner();
}

