async function loadDefaults(){if(!state.animal)return;try{state.defaults=await api(`defaults?animal_id=${encodeURIComponent(state.animal.id)}`)}catch{state.defaults=null}}
async function updateNavBadges(){
  try{
    const aside=document.querySelector('aside'); if(!aside||!state.user) return;
    let due=state.dueReminders?.length||0;
    let hw=0, med=0;
    try{
      const [h,m] = await Promise.all([
        api('homework').catch(()=>({homework:[]})),
        api('medications?active=1').catch(()=>({medications:[]}))
      ]);
      hw=(h.homework||[]).filter(x=>x.status==='active'||x.status==='open'||!x.status).length;
      med=(m.medications||m.items||[]).length;
    }catch{}
    const map={
      calendar: due,
      training: hw,
      vet: med
    };
    aside.querySelectorAll('[data-view]').forEach(btn=>{
      const v=btn.dataset.view;
      let badge=btn.querySelector('.nav-badge');
      const n=map[v]||0;
      if(n>0){
        if(!badge){ badge=document.createElement('span'); badge.className='nav-badge'; btn.appendChild(badge); }
        badge.textContent=n>99?'99+':String(n);
        badge.hidden=false;
      }else if(badge){
        badge.hidden=true;
      }
    });
  }catch(e){ console.warn('nav badges', e); }
}
