function localDayBounds(){const d=new Date();d.setHours(0,0,0,0);const e=new Date(d);e.setDate(e.getDate()+1);return {from:d.toISOString(),to:e.toISOString(),label:d.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}}
function animalSpeciesIcon(a){
  let iconId = a?.avatar_icon;
  if(!iconId || !ANIMAL_ICON_SRCS[String(iconId)]){
    // Deterministic fallback from animal id so icon doesn't jump on re-render
    const seed = String(a?.id || a?.name || '0');
    let h = 0;
    for(let i=0;i<seed.length;i++) h = ((h<<5)-h) + seed.charCodeAt(i) | 0;
    iconId = String((Math.abs(h) % ANIMAL_ICON_COUNT) + 1);
  }
  return animalIconImg(iconId, 'animal-species-icon');
}
function defaultViewForRole(){
  const r=state.user?.effective_role||state.user?.role||'owner';
  if(r==='trainer') return 'training';
  if(r==='keeper') return 'food';
  if(r==='vet') return 'vet';
  if(r==='admin') return 'animals';
  return 'home'; // owner
}
