function isAllAnimals(){return state.animal===null&&state.animals.length>0}
function scopeToolbar(){const opts=[['date_desc','Новые → старые'],['date_asc','Старые → новые'],['name_asc','По алфавиту А → Я'],['name_desc','По алфавиту Я → А']];return `<div class="scope-toolbar"><span class="muted">Все животные · сортировка</span><select id="scopeSort">${opts.map(([v,l])=>`<option value="${v}" ${state.scopeSort===v?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function sortRows(rows,kind){const mode=state.scopeSort||'date_desc';const dk={observations:'observed_at',training:'started_at',vet:'updated_at',food:'logged_at',reminders:'remind_at',schedule:'scheduled_at'}[kind];return [...(rows||[])].sort((a,b)=>{const na=String(a.animal_name||''),nb=String(b.animal_name||'');if(mode==='name_asc'||mode==='name_desc'){const c=na.localeCompare(nb,'ru',{sensitivity:'base'});if(c)return mode==='name_desc'?-c:c}if(dk){const d=new Date(a[dk]||0)-new Date(b[dk]||0);if(d)return mode==='date_asc'?d:-d}return na.localeCompare(nb,'ru',{sensitivity:'base'});});}


/**
 * Журнал: параллельно тянет sessions/obs/vet/food/hw/reminders/schedule/meds/enrichment
 * по каждому животному, склеивает в {type,title,time,meta}, фильтр + сортировка на клиенте.
 */
async function journal(c){
 state.homeTab='journal';
 const __hub=typeof homeHubBar==='function'?homeHubBar():'';if(!state.animals.length){c.innerHTML=__hub+`<div class="card empty-state empty-hero"><div class="empty-icon">▤</div><h3>Журнал</h3><p class="muted">Единая история событий появится после добавления животного: тренировки, наблюдения, рацион, ветеринария.</p><div class="empty-actions"><button type="button" class="primary" id="goAnimalsFromJournal">К животным</button></div></div>`;document.querySelector('#goAnimalsFromJournal')?.addEventListener('click',()=>view('animals'));return}
 const animalLabel=isAllAnimals()?'Все животные':(state.animal?.name||'Животное');
 c.innerHTML=`<div class="top"><div><h2><span class="ui-emoji" aria-hidden="true">▤</span> Журнал</h2><p class="muted">${esc(animalLabel)} · единая история событий</p></div><div class="journal-controls"><input type="search" id="journalSearch" class="search-input" placeholder="Поиск по журналу…" autocomplete="off"><select id="journalType"><option value="all">Все события</option><option value="training">Тренировки</option><option value="observation">Наблюдения</option><option value="vet">Ветеринария</option><option value="medication">Лекарства</option><option value="food">Рацион</option><option value="homework">Домашние задания</option><option value="reminder">Напоминания</option><option value="enrichment">Обогащение среды</option><option value="schedule">Запланированные</option></select><select id="journalSort"><option value="date_desc">Новые → старые</option><option value="date_asc">Старые → новые</option><option value="name_asc">А → Я</option></select></div></div><div id="journalBody" class="journal-list"><div class="skeleton-stack"><div class="skeleton-line"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></div></div><div class="journal-toolbar"><button type="button" class="secondary" id="exportJournalCsv" title="Скачать CSV">↓ Экспорт CSV</button></div>`;
 const aids=isAllAnimals()?state.animals.map(a=>a.id):(state.animal?[state.animal.id]:[]);
 if(!aids.length){c.querySelector('#journalBody').innerHTML='<div class="card"><p class="muted">Создайте карточку или введите код животного.</p></div>';return;}
 try{
  const bundles=await Promise.all(aids.map(async aid=>{
    const [sessions,obs,vet,food,hw,rem,sch,meds,enrich]=await Promise.all([
      api(`sessions?animal_id=${encodeURIComponent(aid)}`).catch(()=>({sessions:[]})),
      api(`observations?animal_id=${encodeURIComponent(aid)}`).catch(()=>({observations:[]})),
      api(`vet?animal_id=${encodeURIComponent(aid)}`).catch(()=>({vet_records:[]})),
      api(`food?animal_id=${encodeURIComponent(aid)}`).catch(()=>({food:[]})),
      api(`homework?animal_id=${encodeURIComponent(aid)}`).catch(()=>({homework:[]})),
      api(`reminders?animal_id=${encodeURIComponent(aid)}`).catch(()=>({reminders:[]})),
      api(`schedule?animal_id=${encodeURIComponent(aid)}`).catch(()=>({schedule:[]})),
      api(`medications?animal_id=${encodeURIComponent(aid)}`).catch(()=>({administrations:[]})),
      api(`enrichment?animal_id=${encodeURIComponent(aid)}`).catch(()=>({enrichment:[]}))
    ]);
    return {a:state.animals.find(x=>x.id===aid),sessions,obs,vet,food,hw,rem,sch,meds,enrich};
  }));
  const all=bundles.flatMap(x=>{
    const items=[];
    arr(x.sessions?.sessions||x.sessions).forEach(r=>items.push({type:'training',animal:x.a,title:'Тренировка',time:r.started_at,meta:`Успех ${r.success_score||'—'}/10 · ${r.duration_minutes||0} мин`,author:r.author||''}));
    arr(x.obs?.observations||x.observations).forEach(r=>items.push({type:'observation',animal:x.a,title:'Наблюдение',time:r.observed_at,meta:r.behavior_note||r.health_note||r.note||'Без комментария',author:r.author||''}));
    arr(x.vet?.vet_records||x.vet).forEach(r=>items.push({type:'vet',animal:x.a,title:r.medication_name||'Ветеринарная запись',time:r.updated_at,meta:[r.record_type,r.frequency].filter(Boolean).join(' · '),author:r.vet_name||''}));
    arr(x.food?.food||x.food_logs).forEach(r=>items.push({type:'food',animal:x.a,title:r.meal||'Рацион',time:r.logged_at,meta:`Съедено: ${r.eaten||'—'}`,author:r.author||''}));
    arr(x.hw?.homework).forEach(r=>items.push({type:'homework',animal:x.a,title:r.title,time:r.updated_at,meta:r.due_date?`Срок: ${r.due_date}`:'Без срока',author:r.trainer_name||''}));
    arr(x.rem?.reminders).forEach(r=>items.push({type:'reminder',animal:x.a,title:r.title,time:r.remind_at,meta:r.enabled?'Активно':'Отключено',author:''}));
    arr(x.sch?.schedule||x.sch?.items||x.sch?.scheduled_items).forEach(r=>items.push({type:'schedule',animal:x.a,title:r.title,time:r.scheduled_at,meta:r.type||'Запланировано',author:''}));
    arr(x.meds?.administrations||x.meds?.prescriptions||x.meds).forEach(r=>{
      if(r.scheduled_at) items.push({type:'medication',animal:x.a,title:r.medication_name||'Препарат',time:r.scheduled_at,meta:(r.status==='given'?'✓ Выдан':'! Не отмечено')+(r.dosage?' · '+r.dosage:''),author:''});
      else if(r.medication_name) items.push({type:'medication',animal:x.a,title:r.medication_name,time:r.start_date||r.created_at,meta:`Курс ${r.start_date||''}—${r.end_date||''} · ${r.frequency_per_day||1}×/день`,author:''});
    });
    arr(x.enrich?.enrichment||x.enrich).forEach(r=>items.push({type:'enrichment',animal:x.a,title:r.title||'Обогащение среды',time:r.logged_at,meta:(r.category||'')+(r.duration_minutes?' · '+r.duration_minutes+' мин':''),author:r.author||''}));
    return items;
  });
  const renderRows=()=>{
   const filter=document.querySelector('#journalType').value, sort=document.querySelector('#journalSort').value;
   const q=(document.querySelector('#journalSearch')?.value||'').trim().toLowerCase();
   let rows=all.filter(r=>filter==='all'||r.type===filter);
   if(q) rows=rows.filter(r=>[r.title,r.meta,r.author,r.animal?.name,r.type].join(' ').toLowerCase().includes(q));
   rows.sort((a,b)=>{if(sort==='name_asc')return String(a.animal?.name||'').localeCompare(String(b.animal?.name||''),'ru',{sensitivity:'base'})||new Date(b.time||0)-new Date(a.time||0);const d=new Date(a.time||0)-new Date(b.time||0);return sort==='date_asc'?d:-d});
   const icons={training:'<span class="ui-emoji" aria-hidden="true">◆</span>️',observation:'<span class="ui-emoji" aria-hidden="true">👁</span>️',vet:'<span class="ui-emoji" aria-hidden="true">✚</span>',medical:'<span class="ui-emoji" aria-hidden="true">✚</span>',medication:'<span class="ui-emoji" aria-hidden="true">💊</span>',food:'<span class="ui-emoji" aria-hidden="true">🍽</span>',homework:'<span class="ui-emoji" aria-hidden="true">⌂</span>',reminder:'<span class="ui-emoji" aria-hidden="true">🔔</span>',schedule:'<span class="ui-emoji" aria-hidden="true">□</span>',enrichment:'<span class="ui-emoji" aria-hidden="true">❧</span>'};
   c.querySelector('#journalBody').innerHTML=rows.map(r=>`<article class="journal-entry"><div class="journal-entry-icon">${icons[r.type]||'•'}</div><div class="journal-entry-main"><div class="journal-entry-top"><b>${esc(r.title)}</b><small>${fmtDate(r.time)}</small></div><p><span class="journal-animal"><span class="ui-emoji" aria-hidden="true">◆</span> ${esc(r.animal?.name||'Животное')}</span>${r.author?' · '+esc(r.author):''}</p><p class="muted">${esc(r.meta||'')}</p></div></article>`).join('')||'<div class="card"><p class="muted">По выбранному фильтру записей нет.</p></div>';
  };
  c.querySelector('#journalType').onchange=renderRows;c.querySelector('#journalSort').onchange=renderRows;c.querySelector('#journalSearch')?.addEventListener('input',renderRows);
  c.querySelector('#exportJournalCsv')?.addEventListener('click',()=>{
    const filter=document.querySelector('#journalType')?.value||'all';
    const q=(document.querySelector('#journalSearch')?.value||'').trim().toLowerCase();
    let rows=all.filter(r=>filter==='all'||r.type===filter);
    if(q) rows=rows.filter(r=>[r.title,r.meta,r.author,r.animal?.name,r.type].join(' ').toLowerCase().includes(q));
    const escCsv=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
    const header=['date','type','animal','title','author','details'];
    const lines=[header.join(',')].concat(rows.map(r=>[r.time,r.type,r.animal?.name||'',r.title||'',r.author||'',r.meta||''].map(escCsv).join(',')));
    const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});
    const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='mostik-journal.csv'; a.click(); URL.revokeObjectURL(a.href);
    try{toast('Журнал экспортирован ('+rows.length+')','ok')}catch{}
  });
  renderRows();
 }catch(e){c.querySelector('#journalBody').innerHTML=`<div class="card error">${esc(e.message)}</div>`}
} 

function loadOwnerTodayPanel(){
  const box=document.querySelector('#ownerTodayPanel');
  if(!box||!state.animal) return;
  const r=state.user.effective_role;
  if(r!=='owner' && r!=='admin'){ box.hidden=true; return; }
  const b=localDayBounds();
  const aid=state.animal.id;
  Promise.all([
    api(`homework?animal_id=${encodeURIComponent(aid)}`).catch(()=>({homework:[]})),
    api(`medications?animal_id=${encodeURIComponent(aid)}`).catch(()=>({prescriptions:[]})),
    api(`schedule?animal_id=${encodeURIComponent(aid)}`).catch(()=>({schedule:[]}))
  ]).then(([hw,med,sch])=>{
    const activeHw=(hw.homework||[]).filter(x=>x.status!=='done');
    const meds=(med.prescriptions||[]).filter(x=>!x.end_date || x.end_date>=new Date().toISOString().slice(0,10));
    const now=Date.now();
    const upcoming=(sch.schedule||[])
      .filter(x=>x.status!=='cancelled' && new Date(x.scheduled_at).getTime()>=now-3600000)
      .sort((a,b)=>new Date(a.scheduled_at)-new Date(b.scheduled_at));
    const next=upcoming[0];
    box.innerHTML=`<h3>Сегодня</h3>
      <div class="owner-today-rows">
        <div class="owner-today-row"><span>ДЗ: <b>${activeHw.length}</b> активных</span><button type="button" class="secondary" data-go="homework">Открыть</button></div>
        <div class="owner-today-row"><span>Лекарства: <b>${meds.length}</b></span><button type="button" class="secondary" data-go="meds">График</button></div>
        <div class="owner-today-row"><span>Ближайшее: <b>${next?esc(next.title||next.type):'—'}</b>${next?` <small class="muted">${fmtDate(next.scheduled_at)}</small>`:''}</span><button type="button" class="secondary" data-go="calendar">Календарь</button></div>
      </div>
`;
    box.querySelectorAll('[data-go]').forEach(btn=>btn.onclick=()=>{
      const g=btn.dataset.go;
      if(g==='homework') view('training');
      else if(g==='meds'){ view('vet'); setTimeout(()=>document.getElementById('vet-section-meds')?.scrollIntoView({behavior:'smooth'}),80); }
      else if(g==='calendar') view('calendar');
    });
    box.querySelectorAll('[data-quick]').forEach(x=>x.onclick=()=>quick(x.dataset.quick));
  }).catch(()=>{ box.innerHTML='<p class="muted">Сводку загрузить не удалось.</p>'; });
}

function careOverview(c){
  const r=state.user.effective_role;
  const title=r==='vet'?'Рацион и занятия':'Рацион и здоровье';
  const sub=r==='vet'
    ? 'Только просмотр: рацион, обогащение среды и тренировки.'
    : 'Только просмотр: рацион и ветеринарные записи.';
  if(!state.animal){
    c.innerHTML=`<div class="card"><h2>${title}</h2><p class="muted">Выберите животное.</p></div>`;
    return;
  }
  const aid=state.animal.id;
  c.innerHTML=`<div class="card"><h2>${title} · ${esc(state.animal.name)}</h2><p class="muted">${sub}</p>
    <div id="careFood"><p class="muted">Загружаю рацион…</p></div>
    <div id="careVet"></div>
    <div id="careExtra"></div>
  </div>`;
  api(`food?animal_id=${encodeURIComponent(aid)}`).then(d=>{
    const rows=(d.food||[]).slice(0,8);
    document.querySelector('#careFood').innerHTML=`<h3>Рацион</h3>${rows.map(x=>`<article class="timeline"><b>${esc(x.meal||'Приём')}</b><small>${fmtDate(x.logged_at)}</small><p>${esc(x.offered||x.products_text||x.note||'')}</p></article>`).join('')||'<p class="muted">Записей рациона пока нет.</p>'}`;
  }).catch(e=>{document.querySelector('#careFood').innerHTML=`<p class="error">${esc(e.message)}</p>`});
  if(r==='trainer'){
    api(`vet?animal_id=${encodeURIComponent(aid)}`).then(d=>{
      const rows=(d.records||[]).slice(0,8);
      document.querySelector('#careVet').innerHTML=`<h3>Ветеринария</h3>${rows.map(x=>`<article class="timeline"><b>${esc(x.medication_name||(x.record_type==='note'?'Состояние':'Запись'))}</b><small>${fmtDate(x.updated_at)}</small>${x.note?`<p class="muted">${esc(x.note)}</p>`:''}</article>`).join('')||'<p class="muted">Записей пока нет.</p>'}`;
    }).catch(()=>{});
  }
  if(r==='vet'){
    api(`enrichment?animal_id=${encodeURIComponent(aid)}`).then(d=>{
      const rows=(d.enrichment||[]).slice(0,5);
      document.querySelector('#careVet').innerHTML=`<h3>Обогащение среды</h3>${rows.map(x=>`<article class="timeline"><b>${esc(x.title||x.category)}</b><small>${fmtDate(x.logged_at)}</small></article>`).join('')||'<p class="muted">Записей пока нет.</p>'}`;
    }).catch(()=>{});
    api(`sessions?animal_id=${encodeURIComponent(aid)}`).then(d=>{
      const rows=(d.sessions||[]).slice(0,5);
      document.querySelector('#careExtra').innerHTML=`<h3>Тренировки</h3>${rows.map(x=>`<article class="timeline"><b>${fmtDate(x.started_at)}</b><small>${esc(x.author||'')}</small></article>`).join('')||'<p class="muted">Сессий пока нет.</p>'}`;
    }).catch(()=>{});
  }
}


