 const categories=['Питание / фуражирование','Движение','Отдых / сон','Самообслуживание / груминг','Исследование','Социальное — положительное','Социальное — отрицательное','Игра','Обогащение','Взаимодействие с кипером','Взаимодействие с посетителями','Территориальное','Репродуктивное','Вокализация','Выделение','Аномальное / стереотипное','Другое'];
