     if(p==='social'){ set('behavior_category','Социальное — положительное'); set('behavior_action','Приближается'); set('state_signs','Спокойное'); set('activity','3'); set('arousal','2'); set('stress','1'); set('behavior_note','Положительный социальный контакт'); }
