  animals.forEach(name=>{const a=obs.filter(x=>x.animal_name===name).sort((x,y)=>new Date(x.observed_at)-new Date(y.observed_at));const pain=a.map(x=>Number(x.pain)).filter(Number.isFinite),app=a.map(x=>Number(x.appetite)).filter(Number.isFinite),act=a.map(x=>Number(x.activity)).filter(Number.isFinite);const last=a.at(-1);if(last&&Number(last.pain)>=4)out.push(['high','Боль',name,`последняя оценка ${last.pain}/5`]);if(last&&Number(last.appetite)<=2)out.push(['medium','Аппетит',name,`последняя оценка ${last.appetite}/5`]);if(last&&Number(last.activity)<=2)out.push(['medium','Активность',name,`последняя оценка ${last.activity}/5`]);if(pain.length>=3&&pain.at(-1)>pain[0])out.push(['high','Тренд боли',name,'показатель растёт']);if(app.length>=3&&app.at(-1)<app[0])out.push(['medium','Тренд аппетита',name,'показатель снижается']);if(act.length>=3&&act.at(-1)<act[0])out.push(['medium','Тренд активности',name,'показатель снижается']);});
