function buildSpecialistAnalytics({sessions,observations,homework,schedule,reminders}){const names=[...new Set([...sessions,...observations,...homework].map(x=>x.author||x.trainer_name).filter(Boolean))];if(!names.length)return '<div class="analytics-empty-state"><b>Нет данных о специалистах</b><span>После первых наблюдений и задач здесь появится распределение работы.</span></div>';const rows=names.map(n=>{const o=observations.filter(x=>(x.author||x.trainer_name)===n).length,s=sessions.filter(x=>(x.author||x.trainer_name)===n).length,h=homework.filter(x=>(x.trainer_name||x.author)===n),done=h.filter(x=>['done','completed'].includes(String(x.status||'').toLowerCase())).length;return {n,o,s,h:h.length,done}}).sort((a,b)=>(b.o+b.s+b.h)-(a.o+a.s+a.h));const max=Math.max(1,...rows.map(r=>r.o+r.s+r.h));return `<div class="specialist-work">${rows.map(r=>`<div class="specialist-row"><div class="specialist-name"><b>${analyticsEsc(r.n)}</b><small>${r.o} наблюд. · ${r.s} трениров. · ДЗ ${r.done}/${r.h}</small></div><div class="work-bar"><i style="width:${Math.round((r.o+r.s+r.h)/max*100)}%"></i></div><strong>${r.o+r.s+r.h}</strong></div>`).join('')}</div><p class="muted analytics-footnote">Это показатель объёма зарегистрированной работы, а не рейтинг качества специалиста.</p>`}
function buildAnimalTimeline({sessions,observations,food,vet,schedule,reminders}){const events=[...observations.map(x=>({t:x.observed_at,type:'Наблюдение',text:x.behavior_action||x.behavior_category||'Оценка состояния'})),...sessions.map(x=>({t:x.started_at,type:'Тренировка',text:x.ending_type||'Занятие'})),...food.map(x=>({t:x.logged_at,type:'Рацион',text:x.meal||'Приём пищи'})),...vet.map(x=>({t:x.updated_at,type:'Ветеринария',text:x.record_type||'Запись'})),...schedule.map(x=>({t:x.scheduled_at,type:'Запланировано',text:x.title||x.type||'Задача'})),...reminders.map(x=>({t:x.remind_at,type:'Напоминание',text:x.title||'Напоминание'}))].filter(x=>x.t).sort((a,b)=>new Date(b.t)-new Date(a.t)).slice(0,30);if(!events.length)return '<div class="analytics-empty-state"><b>Нет событий</b><span>Хронология появится после первых записей.</span></div>';return `<div class="animal-timeline">${events.map(e=>`<div class="timeline-item"><time>${new Date(e.t).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</time><span class="timeline-dot"></span><div><b>${analyticsEsc(e.type)}</b><p>${analyticsEsc(e.text)}</p></div></div>`).join('')}</div>`}
function buildPeriodComparison({observations,sessions,food,days}){const mid=Date.now()-Math.floor(days/2)*86400000;const avgK=(arr,k)=>{const x=arr.filter(v=>Number.isFinite(Number(v[k])));return x.length?(x.reduce((a,v)=>a+Number(v[k]),0)/x.length):null};const make=(from,to)=>{const o=observations.filter(x=>{const t=new Date(x.observed_at).getTime();return t>=from&&t<to});const s=sessions.filter(x=>{const t=new Date(x.started_at).getTime();return t>=from&&t<to});return {activity:avgK(o,'activity'),appetite:avgK(o,'appetite'),concentration:avgK(o,'concentration'),pain:avgK(o,'pain'),observations:o.length,sessions:s.length}};const a=make(Date.now()-days*86400000,mid),b=make(mid,Date.now());const rows=[['Активность','activity'],['Аппетит','appetite'],['Концентрация','concentration'],['Боль','pain']];return `<div class="period-compare"><div class="period-compare-head"><span></span><b>Первая половина</b><b>Вторая половина</b><b>Δ</b></div>${rows.map(([l,k])=>{const av=a[k],bv=b[k],d=av!=null&&bv!=null?bv-av:null;return `<div class="period-compare-row"><span>${l}</span><b>${av==null?'—':av.toFixed(1)}</b><b>${bv==null?'—':bv.toFixed(1)}</b><strong class="${d>0?'trend-up':d<0?'trend-down':'trend-flat'}">${d==null?'—':`${d>0?'+':''}${d.toFixed(1)}`}</strong></div>`}).join('')}</div><p class="muted analytics-footnote">Наблюдения: ${a.observations} → ${b.observations}. Тренировки: ${a.sessions} → ${b.sessions}.</p>`}
