/**
 * Рацион: две вкладки — «Записи» (food_logs) и «План питания» (diets module).
 * state.foodTab сохраняет активную вкладку.
 */

function careTabsForRole(){
  const r=state.user?.effective_role||state.user?.role||'owner';
  const tabs=[];
  if(['owner','trainer','keeper','admin'].includes(r)) tabs.push({id:'observations',label:'Наблюдение'});
  if(['keeper','admin'].includes(r)) tabs.push({id:'enrichment',label:'Обогащение среды'});
  tabs.push({id:'food',label:'Рацион'});
  return tabs;
}
function care(c){
  if(!c) return;
  const tabs=careTabsForRole();
  if(!tabs.length){ c.innerHTML='<div class="card"><p class="muted">Нет доступных подразделов заботы.</p></div>'; return; }
  if(!state.careTab || !tabs.some(x=>x.id===state.careTab)) state.careTab=tabs[0].id;
  c.innerHTML=`<div class="top"><div><h2>Забота</h2><p class="muted">Наблюдение, обогащение среды и рацион — в одном месте. Переключайте вкладки ниже.</p></div></div>
    <div class="care-tabs" role="tablist">${tabs.map(t=>`<button type="button" class="care-tab ${state.careTab===t.id?'active':''}" data-care-tab="${t.id}">${t.label}</button>`).join('')}</div>
    <div id="carePanel" class="care-panel"></div>`;
  c.querySelectorAll('[data-care-tab]').forEach(btn=>{
    btn.onclick=()=>{ state.careTab=btn.dataset.careTab; care(c); };
  });
  const panel=c.querySelector('#carePanel');
  try{
    if(state.careTab==='observations') observations(panel);
    else if(state.careTab==='enrichment') enrichment(panel);
    else food(panel);
  }catch(e){
    panel.innerHTML=`<div class="card app-error"><h3>Не удалось открыть подраздел</h3><p class="muted">${esc(e.message||e)}</p></div>`;
  }
}

